const xs = [1, 2, 3, 4], ys = [3, 5, 7, 9];
let w = 0, b = 0;
const lr = 0.05, n = xs.length;
for (let step = 0; step < 2000; step++) {
  let dw = 0, db = 0;
  xs.forEach((x, i) => {
    const err = w * x + b - ys[i];
    dw += (2 / n) * err * x;
    db += (2 / n) * err;
  });
  w -= lr * dw; b -= lr * db;
}
console.log(w.toFixed(2), b.toFixed(2)); // 2.00 1.00

function softmax(scores) {
  const max = Math.max(...scores);
  const exps = scores.map((s) => Math.exp(s - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map((e) => e / sum);
}

softmax([2, 1, 0.1]); // [0.659, 0.242, 0.099]
softmax([1000, 999]); // [0.731, 0.269], no NaN

const dot = (a, b) =>
  a.reduce((s, x, i) => s + x * b[i], 0);

function attend(q, keys, values) {
  const scale = Math.sqrt(q.length);
  const scores = keys.map((k) => dot(q, k) / scale);
  const w = softmax(scores); // from the softmax card
  return values[0].map((_, j) =>
    w.reduce((s, wi, i) => s + wi * values[i][j], 0));
}

attend([1, 0], [[1, 0], [0, 1]], [[10, 0], [0, 10]]);
// [6.7, 3.3]
